CREATE TABLE CORE.T_FACT_TRAVEL_BOOKING (
   TRAV_BOOKING_SID                    NUMBER          NOT NULL COMMENT 'The unique identifier (surrogate key) for the booking',
   DWH_VALID_FROM_TMSP                 TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record became valid (Timestamp of last process update ).',
   DWH_VALID_TO_TMSP                   TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was no longer valid.',
   DWH_VALID_FG                        BOOLEAN         NOT NULL COMMENT 'An indicator showing the current record in history.',
   BOOKING_NR                          VARCHAR(20)     COMMENT 'Unique Booking ID.',
   TRAV_OFFER_SID                      NUMBER          COMMENT 'The unique identifier (surrogate key) for the customer',
   PROCESS_NR                          VARCHAR(20)     COMMENT 'Unique process ID. Process ID indicates the connection of different services (eg. Travel & insurance booking)',
   CUST_SID                            NUMBER          COMMENT 'The unique identifier (surrogate key) for the customer',
   TRAV_COST_CENTER_CD                 VARCHAR(5)      COMMENT 'The code for the cost center ( for each source market )',
   TRAV_BOOKING_CHANNEL_CD             VARCHAR(5)      COMMENT 'Communication channel where the process was initiated.',
   CUST_BOOKING_REF_SID                NUMBER          COMMENT 'The unique identifier (surrogate key) for customer booking reference link',
   CUST_BOOKING_REF_LINK               VARCHAR(1000)   COMMENT 'The reference link containing EKID & URL identifying the customer touch points incase of offline and online booking',
   TRAV_BOOKING_SVC_TYPE_CD            VARCHAR(20)     COMMENT 'The code for the booking service type ( TOUR - Pauschalreise  , CRUISE - Kreuzfahrt etc )',
   TOUR_OPERATOR_CD                    VARCHAR(50)     COMMENT 'Abbreviation of the tour operator ( also known as provider) , no master data is available',
   TOUR_OPERATOR_AGENCY_CD             VARCHAR(100)    COMMENT 'The code for identifying tour operator agency code',
   BOOKING_DT                          DATE            COMMENT 'Booking date',
   TRAVEL_START_DT                     DATE            COMMENT 'Travel start date ',
   TRAVEL_END_DT                       DATE            COMMENT 'Travel end date ',
   CURR_TRAV_BOOKING_STATUS_CD         VARCHAR(5)      COMMENT 'Current Travel Booking Status Code ( A - active , C - cancelled ). ',
   CANCEL_DT                           DATE            COMMENT 'Cancellation date',
   CHILD_CNT                           NUMBER          COMMENT 'Number of kinder',
   PASSENGER_CNT                       NUMBER          COMMENT 'Number of passengers',
   PASSENGER_TYPE_CLUSTER_CD           VARCHAR(25)     COMMENT 'The code for the categorization of passanger based on their age and gender ( Single traveler , Small Family , etc)',
   FLIGHT_SVC_CD                       VARCHAR(100)    COMMENT 'The code for flight service within the booking',
   CURR_CD                             VARCHAR(5)      COMMENT 'The code identifying the currency according to ISO-4217.',
   INIT_BOOKING_SVC_PRICE_VAL          NUMBER(38, 5)   COMMENT 'Initial booking price ',
   INIT_BOOKING_SVC_PROVISION_VAL      NUMBER(38, 5)   COMMENT 'Initial booking provision ',
   CURR_BOOKING_SVC_PRICE_VAL          NUMBER(38, 5)   COMMENT 'Current booking price ( aditional services can be added or removed )',
   CURR_BOOKING_SVC_PROVISION_VAL      NUMBER(38, 5)   COMMENT 'Current booking provision ( aditional services can be added or removed )',
   CANCEL_PRICE_VAL                    NUMBER(38, 5)   COMMENT 'Cancellation booking price ( filled only if booking is cancelled )',
   CANCEL_PROVISION_VAL                NUMBER(38, 5)   COMMENT 'Cancellation booking  provision ( filled only if booking is cancelled )',
   TRAV_BOOKING_COUPON_CD              VARCHAR(25)     COMMENT 'The codes that customer entered during booking process to activate Coupon.( examples 3001, 3002, etc)',
   COUPON_PRICE_VAL                    NUMBER(38, 5)   COMMENT 'Value of a coupon a customer used for booking a travel. In the data sample of Bosys the value can be identified with the attribute "Preis" in combination with "Type". It is only then a voucher if "type"=fee. All other characterizations of type are related to services (fligth/tour/...)',
   TRAV_BOOKING_COUPON_CUST_CD         VARCHAR(100)    COMMENT 'The codes that customer entered during booking process to activate Coupon.( examples 3001, 3002, etc)',
   IS_FLIGHT_SVC_AVAIL_FG              BOOLEAN         COMMENT 'The indicator to identify if flight service is available in the booking',
   DEPARTURE_AIRPORT_CD                VARCHAR(5)      COMMENT 'Departure Airport for outbound flight (IATA 3 letter code) , no master data is available',
   ARRIVAL_AIRPORT_CD                  VARCHAR(5)      COMMENT 'Arrival Airport for outbound flight (IATA 3 letter code)  , no master data is available',
   DESTINATION_COUNTRY_CD              VARCHAR(5)      COMMENT 'Destination country code',
   DESTINATION_REGION_NAME             VARCHAR(100)    COMMENT 'Destination region name',
   CRUISE_REGION_NAME                  VARCHAR(100)    COMMENT 'Cruise region name',
   TRAV_BOOKING_ROOM_TYPE_CD           VARCHAR(50)     COMMENT 'Accomodation code (EZ-single room; DZ-double room;…)',
   TRAV_BOOKING_FOOD_PACK_TYPE_CD      VARCHAR(5)      COMMENT 'The code for the food & beverage packages (All inclusive | half board | …)',
   IS_HOTEL_SVC_AVAIL_FG               BOOLEAN         COMMENT 'The indicator to identify if hotel service is available in the booking',
   HOTEL_SVC_CD                        VARCHAR(20)     COMMENT 'The code for hotel service within the booking',
   HOTEL_GIATA_NR                      VARCHAR(20)     COMMENT 'Identification Code for an accomodation.',
   HOTEL_CITY_NAME                     VARCHAR(100)    COMMENT 'If an offer contains a GIATA ID , fulltext name of the city the accomodation is located',
   IS_MISC_SVC_AVAIL_FG                BOOLEAN         COMMENT 'The indicator to identify if other service is available in the booking',
   CURR_TRAV_BOOKING_SVC_STATUS_CD     VARCHAR(5)      COMMENT 'The current code for the status of  travel  service ( c-open,  b-booking , etc ). In case of cancellation, this value will be overwritten with the CURRENT value (C - cancelled) and the initial value will be stored in the column init_booking_svc_status_cd.',
   INIT_TRAV_BOOKING_SVC_STATUS_CD     VARCHAR(20)     COMMENT 'The initial code for the status of  travel  service ( c-open,  b-booking , etc ). In case of cancellation, this initial value for the travel booking status will be stored here. ',
   TRAV_BOOKING_DIST_SYS_CD            VARCHAR(5)      COMMENT 'The code for the general distribution system',
   OFFER_OPERATOR_CD                   VARCHAR(100)    COMMENT 'The code for the travel offer operator',
   DWH_CREATED_TMSP                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
   DWH_UPDATED_TMSP                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last updated.',
   DWH_SRC_FILE_NAME                   VARCHAR(255)    NOT NULL COMMENT 'The path and the name of the file(s) from which this record was loaded.',
   SRC_FILE_TMSP                       TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was extracted from the source.',
   SRC_TABLE_NAME                      VARCHAR(100)    COMMENT 'The name of the source table',
   CONSTRAINT PK_T_FACT_TRAVEL_BOOKING PRIMARY KEY (TRAV_BOOKING_SID, DWH_VALID_FROM_TMSP) NOT ENFORCED
 )  COMMENT= 'The fact table with the booking details of service for travel done by customer';
